"""Build the course review slides with Python's standard library only."""
from pathlib import Path
from zipfile import ZipFile, ZIP_DEFLATED
from xml.sax.saxutils import escape

OUT = Path(__file__).with_name("SE_Project_Evaluation.pptx")
EMU = 914400
slides = [
    ("01 / SOFTWARE ENGINEERING", "From a customer brief\nto a delivery plan.", "An agentic requirements and SDLC assistant\nFirst course project evaluation", ["FIELDNOTE", "LOAN APPLICATION ASSISTANT", "TEAM PRESENTATION"]),
    ("THE PROJECT", "Two decisions shape\na software project.", "Start with a real customer need. Make the scope explicit before choosing how to build it.", ["01  What does the system need to do?", "02  Which development lifecycle fits?", "One scenario · two focused agents · reviewable reasoning"]),
    ("AGENT ARCHITECTURE", "A small pipeline, with\na human review point.", "Each agent has one clear responsibility. Outputs from the first agent become evidence for the second.", ["CUSTOMER SCENARIO  →  REQUIREMENTS AGENT", "Source matching · requirement drafting · traceability", "HUMAN REVIEW  →  SDLC ADVISOR", "Project characteristics · model comparison · recommendation"]),
    ("AGENT 01 · REQUIREMENTS", "Translate intent into\ntraceable requirements.", "The first agent identifies functional requirements and links supported details to the project source set.", ["R1  Submit a loan application form online.", "R2  Flag applicants with a current loan for special evaluation.", "Source trail: EDF Loan Management SRS · chunks 27 and 32", "Human approval remains pending before implementation."]),
    ("AGENT 02 · LIFECYCLE", "Choose an SDLC from\nproject conditions.", "The second agent compares fit signals against the lecture-based selection rules and makes unknowns visible.", ["Seven models compared against the known project characteristics", "Iterative / Incremental is a candidate when details may evolve", "Unknown: change frequency, release cadence, project duration", "The advisor withholds a firm recommendation when evidence is too thin."]),
    ("DEMO WALKTHROUGH", "A short path through\nthe working interface.", "The web demo has separate pages for each agent, with editable inputs and visible outputs.", ["01  Open Requirements agent · edit the customer scenario", "02  Review requirement text and source trail", "03  Open SDLC advisor · change project characteristics", "04  Compare model scores and discuss unresolved questions"]),
    ("PROJECT STRUCTURE", "Clear pages. Clear\nresponsibilities.", "A browser-first demo and a compact project workspace support the evaluation walkthrough.", ["web/  overview, requirements page, SDLC page, assets", "presentation/  evaluation deck and deck builder", "docs/  run guide and project notes", "Existing source PDFs, extracted evidence, and Python agent pipeline retained"]),
]

def shape(i, x, y, w, h, text, size=1800, color="182B27", bold=False, fill=None, font="Aptos"):
    paragraphs = ''.join(f'<a:p><a:pPr/><a:r><a:rPr lang="en-US" sz="{size}" b="{int(bold)}"><a:solidFill><a:srgbClr val="{color}"/></a:solidFill><a:latin typeface="{font}"/></a:rPr><a:t>{escape(line)}</a:t></a:r><a:endParaRPr lang="en-US" sz="{size}"/></a:p>' for line in text.split('\n'))
    fill_xml = '<a:solidFill><a:srgbClr val="%s"/></a:solidFill>' % fill if fill else '<a:noFill/>'
    return f'<p:sp><p:nvSpPr><p:cNvPr id="{i}" name="Text {i}"/><p:cNvSpPr txBox="1"/><p:nvPr/></p:nvSpPr><p:spPr><a:xfrm><a:off x="{int(x*EMU)}" y="{int(y*EMU)}"/><a:ext cx="{int(w*EMU)}" cy="{int(h*EMU)}"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom>{fill_xml}<a:ln><a:noFill/></a:ln></p:spPr><p:txBody><a:bodyPr wrap="square" lIns="100000" tIns="70000" rIns="100000" bIns="50000"/><a:lstStyle/>{paragraphs}</p:txBody></p:sp>'

def slide_xml(n, data):
    eyebrow, title, sub, bullets = data
    body = [shape(2, .72, .5, 11.8, .38, eyebrow, 1050, "507460", True, font="Aptos Mono"),
            shape(3, .72, 1.05, 11.8, 1.5, title, 3100, "182B27", True, font="Georgia"),
            shape(4, .8, 2.8, 11.5, .78, sub, 1500, "687872")]
    for i, line in enumerate(bullets):
        body.append(shape(5+i, .82, 3.85+i*.62, 11.2, .48, ("•  " if n not in (1,7) else "")+line, 1550 if n in (1,7) else 1450, "245D4B" if i==0 else "384942", i==0))
    body.extend([shape(20, .72, 7.08, 8, .22, "FIELDNOTE   /   SE PROJECT", 900, "829088", True, font="Aptos Mono"), shape(21, 11.5, 7.08, 1, .22, f"{n:02d} / 07", 900, "829088", False, font="Aptos Mono")])
    bg = '<p:bg><p:bgPr><a:solidFill><a:srgbClr val="F6F7F2"/></a:solidFill><a:effectLst/></p:bgPr></p:bg>'
    return f'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><p:sld xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main">{bg}<p:cSld><p:spTree><p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr><p:grpSpPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="0" cy="0"/><a:chOff x="0" y="0"/><a:chExt cx="0" cy="0"/></a:xfrm></p:grpSpPr>{"".join(body)}</p:spTree></p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sld>'

ct = ['<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>','<Default Extension="xml" ContentType="application/xml"/>','<Override PartName="/ppt/presentation.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.presentation.main+xml"/>']
ct.extend(['<Override PartName="/ppt/slideMasters/slideMaster1.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slideMaster+xml"/>','<Override PartName="/ppt/slideLayouts/slideLayout1.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slideLayout+xml"/>','<Override PartName="/ppt/theme/theme1.xml" ContentType="application/vnd.openxmlformats-officedocument.theme+xml"/>'])
rels = []
for n in range(1, len(slides)+1):
    ct.append(f'<Override PartName="/ppt/slides/slide{n}.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slide+xml"/>')
    rels.append(f'<Relationship Id="rId{n}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slide" Target="slides/slide{n}.xml"/>')
ct_xml = '<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'+''.join(ct)+'</Types>'
presentation = '<?xml version="1.0" encoding="UTF-8"?><p:presentation xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main"><p:sldMasterIdLst/><p:sldIdLst>'+''.join(f'<p:sldId id="{255+n}" r:id="rId{n}"/>' for n in range(1,len(slides)+1))+'</p:sldIdLst><p:sldSz cx="12192000" cy="6858000"/><p:notesSz cx="6858000" cy="9144000"/><p:defaultTextStyle><a:defPPr><a:defRPr lang="en-US"/></a:defPPr></p:defaultTextStyle></p:presentation>'
presentation = presentation.replace('<p:sldMasterIdLst/>', '<p:sldMasterIdLst><p:sldMasterId id="2147483648" r:id="rId99"/></p:sldMasterIdLst>')
rootrels = '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="ppt/presentation.xml"/></Relationships>'
with ZipFile(OUT, 'w', ZIP_DEFLATED) as z:
    z.writestr('[Content_Types].xml', ct_xml)
    z.writestr('_rels/.rels', rootrels)
    z.writestr('ppt/presentation.xml', presentation)
    z.writestr('ppt/_rels/presentation.xml.rels', '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'+''.join(rels)+'<Relationship Id="rId99" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideMaster" Target="slideMasters/slideMaster1.xml"/></Relationships>')
    z.writestr('ppt/slideMasters/slideMaster1.xml', '<?xml version="1.0" encoding="UTF-8"?><p:sldMaster xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main"><p:cSld><p:spTree><p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr><p:grpSpPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="0" cy="0"/><a:chOff x="0" y="0"/><a:chExt cx="0" cy="0"/></a:xfrm></p:grpSpPr></p:spTree></p:cSld><p:clrMap bg1="lt1" tx1="dk1" bg2="lt2" tx2="dk2" accent1="accent1" accent2="accent2" accent3="accent3" accent4="accent4" accent5="accent5" accent6="accent6" hlink="hlink" folHlink="folHlink"/><p:sldLayoutIdLst><p:sldLayoutId id="1" r:id="rId1"/></p:sldLayoutIdLst></p:sldMaster>')
    z.writestr('ppt/slideMasters/_rels/slideMaster1.xml.rels', '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideLayout" Target="../slideLayouts/slideLayout1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/theme" Target="../theme/theme1.xml"/></Relationships>')
    z.writestr('ppt/slideLayouts/slideLayout1.xml', '<?xml version="1.0" encoding="UTF-8"?><p:sldLayout xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main" type="blank" preserve="1"><p:cSld name="Blank"><p:spTree><p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr><p:grpSpPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="0" cy="0"/><a:chOff x="0" y="0"/><a:chExt cx="0" cy="0"/></a:xfrm></p:grpSpPr></p:spTree></p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sldLayout>')
    z.writestr('ppt/slideLayouts/_rels/slideLayout1.xml.rels', '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideMaster" Target="../slideMasters/slideMaster1.xml"/></Relationships>')
    z.writestr('ppt/theme/theme1.xml', '<?xml version="1.0" encoding="UTF-8"?><a:theme xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" name="Fieldnote"><a:themeElements><a:clrScheme name="Fieldnote"><a:dk1><a:srgbClr val="182B27"/></a:dk1><a:lt1><a:srgbClr val="FFFFFF"/></a:lt1><a:dk2><a:srgbClr val="245D4B"/></a:dk2><a:lt2><a:srgbClr val="F6F7F2"/></a:lt2><a:accent1><a:srgbClr val="245D4B"/></a:accent1><a:accent2><a:srgbClr val="D8ED9E"/></a:accent2><a:accent3><a:srgbClr val="E9A06A"/></a:accent3><a:accent4><a:srgbClr val="687872"/></a:accent4><a:accent5><a:srgbClr val="78A686"/></a:accent5><a:accent6><a:srgbClr val="829088"/></a:accent6><a:hlink><a:srgbClr val="245D4B"/></a:hlink><a:folHlink><a:srgbClr val="507460"/></a:folHlink></a:clrScheme><a:fontScheme name="Fieldnote"><a:majorFont><a:latin typeface="Georgia"/></a:majorFont><a:minorFont><a:latin typeface="Aptos"/></a:minorFont></a:fontScheme><a:fmtScheme name="Fieldnote"><a:fillStyleLst><a:solidFill><a:schemeClr val="accent1"/></a:solidFill></a:fillStyleLst><a:lnStyleLst><a:ln w="6350"><a:solidFill><a:schemeClr val="accent1"/></a:solidFill></a:ln></a:lnStyleLst><a:effectStyleLst><a:effectStyle><a:effectLst/></a:effectStyle></a:effectStyleLst><a:bgFillStyleLst><a:solidFill><a:schemeClr val="lt2"/></a:solidFill></a:bgFillStyleLst></a:fmtScheme></a:themeElements></a:theme>')
    for n, data in enumerate(slides, 1):
        z.writestr(f'ppt/slides/slide{n}.xml', slide_xml(n, data))
        z.writestr(f'ppt/slides/_rels/slide{n}.xml.rels', '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideLayout" Target="../slideLayouts/slideLayout1.xml"/></Relationships>')
print(OUT)
